import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_matmul_detail {

constexpr int TILE_M = 64;
constexpr int TILE_N = 64;
constexpr int TILE_K = 8;
constexpr int THREADS = 256;
constexpr int ITEMS_M = 4;
constexpr int ITEMS_N = 4;

__global__ void cute_matmul_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    extern __shared__ float smem[];
    float* smem_A = smem;
    float* smem_B = smem + TILE_M * TILE_K;

    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K, N),
        make_stride(N, Int<1>{}));

    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(M, N),
        make_stride(N, Int<1>{}));

    auto sA = make_tensor(
        make_smem_ptr(smem_A),
        make_shape(Int<TILE_M>{}, Int<TILE_K>{}),
        make_stride(Int<TILE_K>{}, Int<1>{}));

    auto sB = make_tensor(
        make_smem_ptr(smem_B),
        make_shape(Int<TILE_K>{}, Int<TILE_N>{}),
        make_stride(Int<TILE_N>{}, Int<1>{}));

    int tid = threadIdx.x;
    int row_group = tid / 16;
    int col_group = tid % 16;

    int row_base = row_group * ITEMS_M;
    int col_base = col_group * ITEMS_N;

    float accum[ITEMS_M][ITEMS_N];

    #pragma unroll
    for (int i = 0; i < ITEMS_M; ++i) {
        #pragma unroll
        for (int j = 0; j < ITEMS_N; ++j) {
            accum[i][j] = 0.0f;
        }
    }

    int block_row = blockIdx.y * TILE_M;
    int block_col = blockIdx.x * TILE_N;

    for (int k0 = 0; k0 < K; k0 += TILE_K) {
        constexpr int A_VECS = (TILE_M * TILE_K) / 4;
        for (int v = tid; v < A_VECS; v += THREADS) {
            int linear = v * 4;
            int local_m = linear / TILE_K;
            int local_k = linear % TILE_K;
            int global_m = block_row + local_m;
            int global_k = k0 + local_k;
            float* dst = smem_A + local_m * TILE_K + local_k;
            if (global_m < M && global_k + 3 < K &&
                ((reinterpret_cast<unsigned long long>(A) +
                  static_cast<unsigned long long>(global_m * K + global_k) * sizeof(float)) & 15ULL) == 0ULL) {
                *reinterpret_cast<float4*>(dst) =
                    *reinterpret_cast<const float4*>(A + global_m * K + global_k);
            } else {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int lk = local_k + x;
                    int gk = k0 + lk;
                    dst[x] = (global_m < M && gk < K) ? A[global_m * K + gk] : 0.0f;
                }
            }
        }
        constexpr int B_VECS = (TILE_K * TILE_N) / 4;
        for (int v = tid; v < B_VECS; v += THREADS) {
            int linear = v * 4;
            int local_k = linear / TILE_N;
            int local_n = linear % TILE_N;
            int global_k = k0 + local_k;
            int global_n = block_col + local_n;
            float* dst = smem_B + local_k * TILE_N + local_n;
            if (global_k < K && global_n + 3 < N &&
                ((reinterpret_cast<unsigned long long>(B) +
                  static_cast<unsigned long long>(global_k * N + global_n) * sizeof(float)) & 15ULL) == 0ULL) {
                *reinterpret_cast<float4*>(dst) =
                    *reinterpret_cast<const float4*>(B + global_k * N + global_n);
            } else {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int ln = local_n + x;
                    int gn = block_col + ln;
                    dst[x] = (global_k < K && gn < N) ? B[global_k * N + gn] : 0.0f;
                }
            }
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            float a_frag[ITEMS_M];
            float b_frag[ITEMS_N];

            #pragma unroll
            for (int i = 0; i < ITEMS_M; ++i) {
                a_frag[i] = sA(row_base + i, kk);
            }

            #pragma unroll
            for (int j = 0; j < ITEMS_N; ++j) {
                b_frag[j] = sB(kk, col_base + j);
            }

            #pragma unroll
            for (int i = 0; i < ITEMS_M; ++i) {
                #pragma unroll
                for (int j = 0; j < ITEMS_N; ++j) {
                    accum[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }

        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < ITEMS_M; ++i) {
        int global_m = block_row + row_base + i;
        if (global_m < M) {
            #pragma unroll
            for (int j = 0; j < ITEMS_N; ++j) {
                int global_n = block_col + col_base + j;
                if (global_n < N) {
                    gC(global_m, global_n) = accum[i][j];
                }
            }
        }
    }
}

} // namespace cute_matmul_detail

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    int M = static_cast<int>(A_contig.size(0));
    int K = static_cast<int>(A_contig.size(1));
    int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::TILE_N - 1) / cute_matmul_detail::TILE_N,
        (M + cute_matmul_detail::TILE_M - 1) / cute_matmul_detail::TILE_M);

    constexpr size_t shared_bytes =
        (cute_matmul_detail::TILE_M * cute_matmul_detail::TILE_K + cute_matmul_detail::TILE_K * cute_matmul_detail::TILE_N) * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matmul_detail::cute_matmul_kernel<<<grid, block, shared_bytes, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix multiplication kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

